#!/usr/bin/env bash
# СУДИТ: hooks/install-drift-notice.sh
# probe_D1211 — напоминание о дрейфе установки печатает владельцу команды, которые выполнятся из терминала как есть:
# все три (перенос, пересборка seed, сухой прогон) исполняются в bash и zsh из чужого каталога на репозитории, чьё имя
# несёт пробел, апостроф, `$(…)`, обратные кавычки и `$HOME`, — нужный скрипт запускается, лишнего не исполнено (ноги
# T2c–T2e его теста). Поиск прежней формы по имени переменной снят: он был привязан к `REPO` и пропускал её синонимы
# (финальный скептик D1211, M1) — поведение судит исполнение.
# Красная (1), пока хоть одна команда не выполнится как напечатана; 2 — нет хука или его теста.
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
H="$R/hooks/install-drift-notice.sh"
[ -f "$H" ] && [ -f "$R/hooks/tests/test_install_drift_notice.sh" ] || exit 2
DRIFT_NOTICE="$H" bash "$R/hooks/tests/test_install_drift_notice.sh" >/dev/null 2>&1 \
    || { echo "тест напоминания красен: команда не выполнится как напечатана (ноги T2c–T2e)"; exit 1; }
echo "напоминание о дрейфе печатает команды, исполнимые из терминала как есть"
exit 0
